CREATE TABLE question_assets (id CHAR(36) PRIMARY KEY, question_id CHAR(36) NOT NULL, page_number INT NOT NULL, path VARCHAR(1024) NOT NULL, mime_type VARCHAR(100) NOT NULL, sort_order INT NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_question_assets_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE, INDEX idx_question_assets_question (question_id));
